<?php declare(strict_types=1); $studentDashboard = $studentDashboard ?? []; ?>
<section class="view hidden" id="view-student-dashboard" data-title="Dashboard" data-section="Student workspace">
  <div class="page-heading"><div><span class="eyebrow">YOUR CLUBCONNECT</span><h1>Welcome back, <?= e($currentUser['first_name'] ?? 'student') ?></h1><p class="muted">Here is what is happening around your campus.</p></div><button class="button button-primary" data-view="events">Explore events <span>→</span></button></div>
  <div class="metric-grid"><article class="metric-card"><span class="metric-icon blue">♧</span><div><strong><?= e($studentDashboard['joined_clubs'] ?? 0) ?></strong><span>Joined clubs</span></div></article><article class="metric-card"><span class="metric-icon orange">◫</span><div><strong><?= e($studentDashboard['upcoming_events'] ?? 0) ?></strong><span>Upcoming registrations</span></div></article><article class="metric-card"><span class="metric-icon green">✦</span><div><strong><?= e($studentDashboard['available_clubs'] ?? 0) ?></strong><span>Available clubs</span></div></article></div>
  <div class="dashboard-grid"><article class="panel schedule-panel"><div class="panel-heading"><div><h2>Your registered events</h2><p class="muted">Do not miss your next experience.</p></div><button class="text-button" data-view="registrations">View all →</button></div><?php if ($userRegistrations === []): ?><div class="empty-state"><p class="muted">You have no upcoming registered events.</p><button class="button button-outline" data-view="events">Find an event</button></div><?php else: ?><div class="event-list"><?php foreach (array_slice($userRegistrations, 0, 3) as $registration): ?><a class="event-row" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $registration['event_id'] ?>"><span class="date-tile"><strong><?= e(date('d', strtotime((string) $registration['event_date']))) ?></strong><span><?= e(strtoupper(date('M', strtotime((string) $registration['event_date'])))) ?></span></span><span class="event-info"><strong><?= e($registration['title']) ?></strong><span><?= e(date('g:i A', strtotime((string) $registration['event_time']))) ?> · <?= e($registration['venue']) ?></span></span><span class="tag tag-blue"><?= e(ucfirst((string) $registration['status'])) ?></span></a><?php endforeach; ?></div><?php endif; ?></article><article class="panel club-panel"><div class="panel-heading"><div><h2>Your clubs</h2><p class="muted">Communities you are part of.</p></div><button class="text-button" data-view="clubs">Explore →</button></div><?php if ($userClubs === []): ?><div class="empty-state"><p class="muted">You have not joined any clubs yet.</p><button class="button button-outline" data-view="clubs">Explore clubs</button></div><?php else: foreach ($userClubs as $club): $tone = club_tone((string) $club['category']); ?><a class="club-mini" data-view="club-details" data-route="true" href="index.php?view=club-details&amp;id=<?= (int) $club['club_id'] ?>"><span class="club-avatar <?= e($tone) ?>">✦</span><div><strong><?= e($club['name']) ?></strong><span><?= e($club['category']) ?></span></div><span class="online-dot"></span></a><?php endforeach; endif; ?></article></div>
  <article class="panel"><div class="panel-heading"><div><h2>Recent registration activity</h2><p class="muted">Your latest event activity.</p></div></div><?php if (($studentDashboard['recent_activity'] ?? []) === []): ?><div class="empty-state"><p class="muted">No registration activity yet.</p></div><?php else: ?><div class="activity-list"><?php foreach ($studentDashboard['recent_activity'] as $activity): ?><a class="activity-row" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $activity['event_id'] ?>"><span class="avatar blue">◫</span><div><strong><?= e($activity['title']) ?></strong><span><?= e($activity['club_name']) ?> · <?= e(ucfirst((string) $activity['status'])) ?></span></div><small><?= e(date('j M Y', strtotime((string) $activity['registered_at']))) ?></small></a><?php endforeach; ?></div><?php endif; ?></article>
</section>
